package i18n

var boot_config_openstackEN = map[string]string{
	"cmd.boot_config_top.apply.account.openstack.block.usage_notes":  "This is the OpenStack block-storage boot-config apply help for cloud account `%s`.\n\nThe account resolves to cloud_type `%s`, storage_type `%s`, provider `%s`.\n\nPrepare the inputs in this order:\n  1. Confirm the target host ID:\n    hyperbdrctl host list\n  2. Review the current host boot configuration:\n    hyperbdrctl boot-config get --id <host_id>\n  3. Confirm the target cloud account and cloud-sync-gateway:\n    hyperbdrctl cloud-account detail --id <account_id>\n    hyperbdrctl cloud-sync-gateway list\n  4. Query the candidate resources for that account:\n    hyperbdrctl cloud-resource fetch --cloud-account-id <account_id> --help\n    hyperbdrctl cloud-resource fetch --cloud-account-id <account_id> --fetch-res zones\n\nThe minimum apply command is:\n  hyperbdrctl boot-config apply \\\n    --id <host_id> \\\n    --cloud-account-id <account_id> \\\n    --storage-id <storage_id>\n\nAdd OpenStack context only when you need it:\n  --project-id / --project-domain-id / --region-id / --compute-zone-id\n  --image-id / --flavor-id / --volume-type-id\n  --network-id / --subnet-id / --security-group-id\n\nTo preload metadata from file, add:\n  --file ./tmp/boot-config.json\n\nTo continue overriding metadata, add:\n  --set key=value\n  --set-json key=<json>\n\nTo inspect the final request body without sending it, add:\n  --preview-request",
	"cmd.boot_config_top.apply.account.openstack.object.usage_notes": "This is the OpenStack object-storage boot-config apply help for cloud account `%s`.\n\nThe account resolves to cloud_type `%s`, storage_type `%s`, provider `%s`.\n\nPrepare the inputs in this order:\n  1. Confirm the target host ID:\n    hyperbdrctl host list\n  2. Review the current host boot configuration:\n    hyperbdrctl boot-config get --id <host_id>\n  3. Confirm the target cloud account and object storage:\n    hyperbdrctl cloud-account detail --id <account_id>\n    hyperbdrctl oss list\n  4. Query the candidate resources for that account:\n    hyperbdrctl cloud-resource fetch --cloud-account-id <account_id> --help\n    hyperbdrctl cloud-resource fetch --cloud-account-id <account_id> --fetch-res zones\n\nThe minimum apply command is:\n  hyperbdrctl boot-config apply \\\n    --id <host_id> \\\n    --cloud-account-id <account_id> \\\n    --storage-id <storage_id>\n\nAdd OpenStack context only when you need it:\n  --project-id / --project-domain-id / --region-id / --compute-zone-id\n  --image-id / --flavor-id\n  --system-volume-type-id / --volume-type-id\n  --network-id / --subnet-id / --security-group-id\n  --boot-loader-image-id / --boot-loader-flavor-id\n\nTo preload metadata from file, add:\n  --file ./tmp/boot-config.json\n\nTo continue overriding metadata, add:\n  --set key=value\n  --set-json key=<json>\n\nTo inspect the final request body without sending it, add:\n  --preview-request",
	"help.boot_config.apply.openstack.block":                         bootConfigApplyOpenstackBlockEN,
	"help.boot_config.apply.openstack.object":                        bootConfigApplyOpenstackObjectEN,
}
